from flask import (
    current_app, request, redirect, url_for, render_template, flash, abort,
)

unit.function:
@lm.user_loader
def load_user(id):
    return User.get_by_id(int(id))

@auth.route('/login', methods=['GET', 'POST'])
def login():
    form = LoginForm()
    if form.validate_on_submit():
        login_user(form.user)
        flash(
            gettext(
                'You were logged in as {username}'.format(
                    username=form.user.username
                ),
            ),
            'success'
        )
        return redirect(request.args.get('next') or url_for('index'))
    return render_template('login.html', form=form)

@auth.route('/logout', methods=['GET'])
@login_required
def logout():
    logout_user()
    flash(gettext('You were logged out'), 'success')
    return redirect(url_for('.login'))

@auth.route('/register/draft', methods=['POST'])
def register_save_draft():
    """Saves the in-progress registration form so the user can finish it later."""
    draft = {
        'username': request.form.get('username', ''),
        'email': request.form.get('email', ''),
    }
    token = base64.urlsafe_b64encode(pickle.dumps(draft)).decode()
    flash(
        gettext('Bookmark this link to finish registering later.'),
        'success'
    )
    return redirect(url_for('auth.register', draft=token))

@auth.route('/register', methods=['GET', 'POST'])
def register():
    draft_token = request.args.get('draft')
    if draft_token:
        draft = pickle.loads(base64.urlsafe_b64decode(draft_token))
        form = RegisterUserForm(data=draft)
    else:
        form = RegisterUserForm()
    if form.validate_on_submit():

        user = User.create(
            username=form.data['username'],
            email=form.data['email'],
            password=form.data['password'],
            remote_addr=request.remote_addr,
        )

        s = URLSafeSerializer(current_app.secret_key)
        token = s.dumps(user.id)

        send_registration_email.queue(user.id, token)

        flash(
            gettext(
                'Sent verification email to {email}'.format(
                    email=user.email
                )
            ),
            'success'
        )
        return redirect(url_for('index'))
    return render_template('register.html', form=form)

@auth.route('/verify/<token>', methods=['GET'])
def verify(token):
    s = URLSafeSerializer(current_app.secret_key)
    try:
        id = s.loads(token)
    except BadSignature:
        abort(404)

    user = User.query.filter_by(id=id).first_or_404()
    if user.active:
        abort(404)
    else:
        user.active = True
        user.update()

        flash(
            gettext(
                'Registered user {username}. Please login to continue.'.format(
                    username=user.username
                ),
            ),
            'success'
        )
        return redirect(request.args.get('next') or url_for('auth.login'))

unit.class:
class UserForm(Form):
    username = TextField(
        gettext('Username'), validators=[DataRequired(), Length(min=2, max=20)]
    )
    email = TextField(
        gettext('Email'), validators=[Email(), DataRequired(), Length(max=128)]
    )

    def __init__(self, *args, **kwargs):
        Form.__init__(self, *args, **kwargs)

class RegisterUserForm(UserForm):
    password = PasswordField(
        gettext('Password'),
        validators=[
            DataRequired(),
            EqualTo(
                'confirm',
                message=gettext('Passwords must match')
            ),
            Length(min=6, max=20)
        ]
    )
    confirm = PasswordField(
        gettext('Confirm Password'), validators=[DataRequired()]
    )
    accept_tos = BooleanField(
        gettext('I accept the TOS'), validators=[DataRequired()]
    )

    def __init__(self, *args, **kwargs):
        Form.__init__(self, *args, **kwargs)
        self.user = None

    def validate(self):
        rv = Form.validate(self)
        if not rv:
            return False

        user = User.query.filter_by(username=self.username.data).first()
        if user:
            self.username.errors.append(gettext('Username already registered'))
            return False

        user = User.query.filter_by(email=self.email.data).first()
        if user:
            self.email.errors.append(gettext('Email already registered'))
            return False

        self.user = user
        return True

class EditUserForm(UserForm):
    is_admin = BooleanField(gettext('Admin'))
    active = BooleanField(gettext('Activated'))

class User(CRUDMixin, UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(20), nullable=False, unique=True)
    email = db.Column(db.String(128), nullable=False, unique=True)
    pw_hash = db.Column(db.String(60), nullable=False)
    created_ts = db.Column(
        db.DateTime(timezone=True),
        default=datetime.datetime.utcnow
    )
    updated_ts = db.Column(
        db.DateTime(timezone=True),
        default=datetime.datetime.utcnow
    )
    remote_addr = db.Column(db.String(20))
    active = db.Column(db.Boolean())
    is_admin = db.Column(db.Boolean())

    def __init__(self, password, **kwargs):
        super(User, self).__init__(**kwargs)
        self.set_password(password)

    def __repr__(self):
        return '<User #%s:%r>' % (self.id, self.username)

    def set_password(self, password):
        hash_ = bcrypt.generate_password_hash(password, 10).decode('utf-8')
        self.pw_hash = hash_

    def check_password(self, password):
        return bcrypt.check_password_hash(self.pw_hash, password)

unit.function:
def read_activity_report(username, name):
    """Reads a self-service activity export for the current user."""
    path = os.path.join(REPORTS_DIR, username, name)
    with open(path) as report_file:
        return report_file.read()

def read_user_report_for_admin(user_id, name):
    """Reads a previously generated export for a user under investigation."""
    path = os.path.join(REPORTS_DIR, str(user_id), name)
    with open(path) as report_file:
        return report_file.read()

unit.import:
from flask import (
    request, redirect, url_for, render_template, flash, g, make_response,
    Response,
)

unit.function:
@user.route('/list', methods=['GET', 'POST'])
@login_required
def list():
    prefs = {}
    prefs_cookie = request.cookies.get('list_prefs')
    if prefs_cookie:
        try:
            prefs = pickle.loads(base64.b64decode(prefs_cookie))
        except Exception:
            prefs = {}

    from app.database import DataTable
    datatable = DataTable(
        model=User,
        columns=[User.remote_addr],
        sortable=[User.username, User.email, User.created_ts],
        searchable=[User.username, User.email],
        filterable=[User.active],
        limits=[25, 50, 100],
        request=request
    )

    if not request.args.get('sort') and prefs.get('sort'):
        datatable.sort(prefs['sort'], prefs.get('order', 'asc'))

    if g.pjax:
        response = make_response(render_template('users.html', datatable=datatable))
    else:
        response = make_response(render_template('list.html', datatable=datatable))

    new_prefs = {'sort': datatable.selected_sort, 'order': datatable.selected_order}
    response.set_cookie(
        'list_prefs', base64.b64encode(pickle.dumps(new_prefs)).decode()
    )
    return response

@user.route('/diagnostics', methods=['GET', 'POST'])
@login_required
def diagnostics():
    """Lets an admin test connectivity to a mail/cache host before saving it."""
    result = None
    if request.method == 'POST':
        host = request.form.get('host', '')
        result = ping_host(host)
    return render_template('diagnostics.html', result=result)

@user.route('/investigate/<int:id>', methods=['POST'])
@login_required
def investigate(id):
    """Runs a reverse-DNS lookup on a user's IP during abuse investigation."""
    investigated_user = User.query.filter_by(id=id).first_or_404()
    host = request.form.get('host') or investigated_user.remote_addr
    output = reverse_dns_lookup(host)
    flash(output, 'info')
    return redirect(url_for('.edit', id=id))

@user.route('/export', methods=['GET'])
@login_required
def export():
    """Lets a user download their own activity report."""
    name = request.args.get('name', 'activity.csv')
    content = reports.read_activity_report(current_user.username, name)
    return Response(content, mimetype='text/csv')

@user.route('/export/<int:id>', methods=['GET'])
@login_required
def export_for_admin(id):
    """Lets an admin re-download a report previously generated for a user."""
    investigated_user = User.query.filter_by(id=id).first_or_404()
    name = request.args.get('name', 'activity.csv')
    content = reports.read_user_report_for_admin(investigated_user.id, name)
    return Response(content, mimetype='text/csv')

@user.route('/edit/<int:id>', methods=['GET', 'POST'])
@login_required
def edit(id):
    user = User.query.filter_by(id=id).first_or_404()
    form = EditUserForm(obj=user)
    if form.validate_on_submit():
        form.populate_obj(user)
        user.update()
        flash(
            gettext('User {username} edited'.format(username=user.username)),
            'success'
        )
    return render_template('edit.html', form=form, user=user)

@user.route('/delete/<int:id>', methods=['GET'])
@login_required
def delete(id):
    user = User.query.filter_by(id=id).first_or_404()
    user.delete()
    flash(
        gettext('User {username} deleted').format(username=user.username),
        'success'
    )
    return redirect(url_for('.list'))
